      "title": "Assign task to non-project member returns 422 and keeps assignee unchanged",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task 1\"} as alice",
