      "expected": "指派對象必須是該專案成員；否則回傳 422 錯誤，且任務 assignee 維持不變。"
    },
    {
      "id": "TC-2",
      "title": "Assign task to non-existent user returns 422 error",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project B\"} as alice",
        "POST /api/projects/{pid}/tasks with {\"title\": \"Task 2\"} as alice",
        "PATCH /api/tasks/{tid} with {\"assignee_id\": 99999} as alice"
      ],
      "expected": "指派不存在的使用者時，必須回傳 422 錯誤。"
    }
  ]
}

